<?php
namespace qqworld_collector\module\static_cache; class post_type_archive extends handler { public function make_cache($post_type) { $url = get_post_type_archive_link($post_type); if (empty($url) || $url == home_url()) return; switch ($this->options->qc_static_cache_mode) { case 'half': $parser = parse_url($url); $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($parser['path']); $this->set_half_cache($path, $url); $uri = preg_match('/\/$/i', $uri) ? $uri : $uri . '/'; $url = preg_match('/\/$/i', $url) ? $url : $url . '/'; $count = wp_count_posts($post_type); if ($count->publish) { $posts_per_page = get_option( 'posts_per_page' ); if ($count->publish > $posts_per_page) { $pages = $count->publish / $posts_per_page; $pages = is_int($pages) ? $pages : intval($pages) + 1; for ($page=2; $page<=$pages; $page++) { $path = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'static-cache' . DIRECTORY_SEPARATOR . md5($uri . 'page/' . $page); $this->set_half_cache($path, $url . 'page/' . $page); } } } break; case 'pure': $url = str_replace(home_url(), '', $url); $path = $this->get_path($url, $this->abspath); $args = "index.php?post_type={$post_type}"; $this->set_pure_cache($path, $args); $count = wp_count_posts($post_type); if ($count->publish) { $posts_per_page = get_option( 'posts_per_page' ); if ($count->publish > $posts_per_page) { $pages = $count->publish / $posts_per_page; $pages = is_int($pages) ? $pages : intval($pages) + 1; for ($page=2; $page<=$pages; $page++) { $path = $this->get_path($url . 'page/' . $page, $this->abspath); $args = "index.php?post_type={$post_type}&paged={$page}"; $this->set_pure_cache($path, $args); } } } break; } } } ?>